//! Turns an approval request's review payload into display lines: a unified diff for file changes, the patch as
//! sent, or the command line. Pure; the sidecar already redacted and capped the text.
use std::ops::Range;
use std::time::Duration;

use similar::{ChangeTag, TextDiff};

use crate::protocol::Review;

const CONTEXT_LINES: usize = 3;
/// Bounds the diff on huge inputs; `similar` falls back to a coarser diff when it runs out of time.
const DIFF_TIMEOUT: Duration = Duration::from_millis(200);

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum LineKind {
    Meta,
    Hunk,
    Added,
    Removed,
    Context,
    Command,
}

#[derive(Clone, Debug, PartialEq)]
pub struct ReviewLine {
    pub kind: LineKind,
    pub text: String,
}

fn line(kind: LineKind, text: impl Into<String>) -> ReviewLine {
    ReviewLine {
        kind,
        text: text.into(),
    }
}

/// A row of a command or script as drawn: tabs as spaces, every other control character (a lone carriage return that
/// would redraw the line, ESC) and bidirectional override shown as a visible stand-in, so what is displayed is what runs.
fn safe_row(row: &str) -> String {
    crate::diff_view::approval_safe_text(&row.replace('\t', "    "))
}

fn truncation_note() -> ReviewLine {
    line(
        LineKind::Meta,
        "… preview truncated; the action uses the full content",
    )
}

/// The rows the approval panel draws for a review. Every row passes through `safe_row` here, whatever its kind or
/// field (a path, a hunk, a command, an argument), so no review text can reach the screen as a control character or an
/// invisible one.
pub fn review_lines(review: &Review) -> Vec<ReviewLine> {
    let mut lines = review_rows(review);
    for row in &mut lines {
        row.text = safe_row(&row.text);
    }
    lines
}

fn review_rows(review: &Review) -> Vec<ReviewLine> {
    let mut lines = Vec::new();
    let truncated = match review {
        Review::Change {
            path,
            before,
            after,
            created,
            truncated,
        } => {
            if *created {
                lines.push(line(LineKind::Meta, format!("new file {path}")));
            } else if before.is_none() {
                lines.push(line(
                    LineKind::Meta,
                    format!(
                        "{path}: current content not shown (outside the workspace, unreadable, or too large)"
                    ),
                ));
            }
            lines.extend(unified(path, before.as_deref().unwrap_or(""), after));
            *truncated
        }
        Review::Patch {
            path,
            patch,
            truncated,
        } => {
            lines.push(line(LineKind::Meta, format!("patch {path}")));
            lines.extend(patch.lines().map(classify));
            *truncated
        }
        Review::Shell { command } => {
            lines.extend(command.lines().enumerate().map(|(index, row)| {
                line(
                    LineKind::Command,
                    format!("{} {row}", if index == 0 { "$" } else { " " }),
                )
            }));
            false
        }
        Review::Verifier {
            command,
            script,
            detail,
        } => {
            if let Some(detail) = detail {
                lines.push(line(LineKind::Meta, format!("verifier: {detail}")));
            }
            lines.extend(command.lines().enumerate().map(|(index, row)| {
                line(
                    LineKind::Command,
                    format!("{} {row}", if index == 0 { "$" } else { " " }),
                )
            }));
            if let Some(script) = script {
                if script != command {
                    lines.push(line(LineKind::Meta, "script:"));
                    lines.extend(script.lines().map(|row| line(LineKind::Context, format!("  {row}"))));
                }
            }
            false
        }
        Review::Args { text, truncated } => {
            lines.extend(text.lines().map(|row| line(LineKind::Context, row)));
            *truncated
        }
        Review::Unknown => {
            lines.push(line(
                LineKind::Meta,
                "This request has no preview this view can show.",
            ));
            false
        }
    };
    if truncated {
        lines.push(truncation_note());
    }
    lines
}

/// `start,len` of a hunk range in unified-diff form; an empty range is written `start,0` like git does.
fn hunk_range(range: Range<usize>) -> String {
    if range.is_empty() {
        format!("{},0", range.start)
    } else if range.len() == 1 {
        format!("{}", range.start + 1)
    } else {
        format!("{},{}", range.start + 1, range.len())
    }
